update public.questions set body_hi = 'लोकसभा में बजट के संदर्भ में ''गिलोटिन'' (guillotine) शब्द का अर्थ है:', explanation_hi = 'अनुदान माँगों पर चर्चा के लिए निर्धारित दिनों के अंतिम दिन अध्यक्ष सभी बची हुई माँगों को, चर्चा हुई हो या नहीं, एक साथ मतदान के लिए रख देते हैं; इसे ''गिलोटिन'' कहते हैं। इससे बजट समय पर पारित हो जाता है, यद्यपि कई माँगें बिना चर्चा के ही पारित हो जाती हैं।', updated_at = now() where id = '4649a5a5-3d76-48be-bfda-0e6441461d3b' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I गलत है: संविधान का कोई प्रावधान अध्यक्ष से अपने दल की सदस्यता छोड़ने की अपेक्षा नहीं करता; भारत ने दल से अलग रहने वाले अध्यक्ष की ब्रिटिश परंपरा नहीं अपनाई है। कथन-II सही है: अनुच्छेद 100(1) के तहत अध्यक्ष पहली बार में मत नहीं देते, पर मत बराबर होने पर निर्णायक मत देते हैं।', updated_at = now(), question_data = question_data || '{"assertion_hi": "लोकसभा का जो सदस्य अध्यक्ष चुना जाता है, संविधान के अनुसार उसे अपने राजनीतिक दल से त्यागपत्र देना होता है।", "reason_hi": "अध्यक्ष पहली बार में मत नहीं देते, पर मत बराबर होने की स्थिति में निर्णायक मत का प्रयोग करते हैं।"}'::jsonb where id = '0e68502b-ca05-4405-90ef-a24eaff82c63' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'द्विसदनीय विधानमंडल वाले राज्य के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1, 2 और 4 सही हैं। अनुच्छेद 197 के तहत विधान परिषद किसी साधारण विधेयक को पहली बार में अधिकतम तीन महीने और दूसरी बार में एक महीने रोक सकती है, जिसके बाद विधानसभा का रूप पारित माना जाता है; राज्य विधानमंडल में संयुक्त बैठक का प्रावधान नहीं है; और परिषद में शुरू हुआ विधेयक विधानसभा द्वारा अस्वीकार होने पर समाप्त हो जाता है। कथन 3 गलत है: परिषद धन विधेयक को अस्वीकार या संशोधित नहीं कर सकती; उसे 14 दिन में लौटाना होता है, और विधानसभा उसकी सिफ़ारिशें मान भी सकती है और ठुकरा भी सकती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["विधान परिषद विधानसभा द्वारा पारित किसी साधारण विधेयक को अधिकतम चार महीने तक रोक सकती है।", "गतिरोध दूर करने के लिए राज्य विधानमंडल के दोनों सदनों की संयुक्त बैठक का कोई प्रावधान नहीं है।", "विधान परिषद विधानसभा द्वारा पारित धन विधेयक को अस्वीकार कर सकती है।", "विधान परिषद में शुरू होने वाला कोई साधारण विधेयक यदि विधानसभा अस्वीकार कर दे, तो वह समाप्त हो जाता है।"]}'::jsonb where id = '2d42de34-aa9c-4ec1-8519-aed53af8af19' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। अनुच्छेद 83(2) के परंतुक के तहत राष्ट्रीय आपातकाल के दौरान संसद कानून बनाकर लोकसभा का कार्यकाल एक बार में एक वर्ष बढ़ा सकती है (और आपातकाल समाप्त होने के बाद छह महीने से आगे नहीं)। अनुच्छेद 172(1) का परंतुक अलग से संसद को राज्य विधानसभा का कार्यकाल इसी तरह बढ़ाने की अनुमति देता है। ये दो अलग सदनों के लिए समानांतर प्रावधान हैं; एक दूसरे का कारण नहीं है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "राष्ट्रीय आपातकाल की उद्घोषणा लागू रहने के दौरान लोकसभा का कार्यकाल पाँच वर्ष से आगे बढ़ाया जा सकता है।", "reason_hi": "राष्ट्रीय आपातकाल की उद्घोषणा लागू रहने के दौरान संसद के कानून द्वारा राज्य विधानसभा का कार्यकाल भी बढ़ाया जा सकता है।"}'::jsonb where id = '7eac28a2-8702-43ee-8515-abd4195d0e64' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'संसद की सदस्यता के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: अनुच्छेद 84 के तहत राज्यसभा के लिए चुने जाने के लिए व्यक्ति की आयु कम से कम 30 वर्ष होनी चाहिए। कथन 1 गलत है: लोकसभा के लिए न्यूनतम आयु 25 वर्ष है; 21 वर्ष किसी भी सदन की योग्यता की आयु नहीं है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["लोकसभा की सदस्यता के लिए न्यूनतम आयु 21 वर्ष है।", "राज्यसभा की सदस्यता के लिए न्यूनतम आयु 30 वर्ष है।"]}'::jsonb where id = 'a6ed5bcb-cd9b-4c94-b6d5-ebf53756c797' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'संसद में कटौती प्रस्तावों (cut motions) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: मितव्ययिता कटौती (economy cut) में माँग को एक निश्चित राशि से घटाने का प्रस्ताव होता है, जो की जा सकने वाली बचत को दर्शाता है। कथन 1 और 3 बाकी दो को आपस में बदल देते हैं: नीति अनुमोदन कटौती (policy cut) माँग को घटाकर 1 रुपया कर देती है, जबकि सांकेतिक कटौती (token cut) किसी विशेष शिकायत को उठाने के लिए माँग को 100 रुपये कम करती है। कथन 4 गलत है: अनुदान माँगों पर मतदान केवल लोकसभा में होता है, इसलिए कटौती प्रस्ताव केवल वहीं लाए जा सकते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["''नीति कटौती'' प्रस्ताव माँग की राशि 100 रुपये कम करने का प्रस्ताव करता है।", "''मितव्ययिता कटौती'' प्रस्ताव माँग की राशि एक निर्दिष्ट रकम से कम करने का प्रस्ताव करता है।", "''सांकेतिक कटौती'' प्रस्ताव माँग की राशि घटाकर 1 रुपया करने का प्रस्ताव करता है।", "कटौती प्रस्ताव संसद के दोनों सदनों में लाए जा सकते हैं।"]}'::jsonb where id = 'a750f319-12ba-42ff-93bb-f608a9741274' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संसदीय विशेषाधिकारों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 2 और 3 सही हैं: विशेषाधिकार उन व्यक्तियों तक फैले हैं जिन्हें सदनों में बोलने का अधिकार है, जैसे महान्यायवादी और केंद्रीय मंत्री; और संसद ने अपने विशेषाधिकारों को संहिताबद्ध नहीं किया है (अनुच्छेद 105(3) इन्हें जैसे हैं वैसे बनाए रखता है)। कथन 1 गलत है: राष्ट्रपति संसद का अभिन्न अंग होते हुए भी संसदीय विशेषाधिकार नहीं रखते। कथन 4 गलत है: गिरफ़्तारी से छूट केवल दीवानी मामलों में, सत्र के दौरान तथा उसके 40 दिन पहले और बाद तक, लागू होती है; आपराधिक या निवारक निरोध के मामलों में नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संसदीय विशेषाधिकार राष्ट्रपति को उपलब्ध हैं, क्योंकि वे संसद के अभिन्न अंग हैं।", "संसदीय विशेषाधिकार भारत के महान्यायवादी को भी उपलब्ध हैं।", "संसद ने अब तक अपने सदनों और सदस्यों के सभी विशेषाधिकारों को संहिताबद्ध करने वाला कोई कानून नहीं बनाया है।", "संसद के सत्र के दौरान संसद सदस्यों को आपराधिक मामलों में गिरफ़्तारी से छूट मिलती है।"]}'::jsonb where id = 'c98d58f3-3121-435e-9d21-39af4a844693' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संसदीय प्रस्तावों और उनकी विशेषताओं के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल युग्म 1 और 4 सही हैं: राज्यसभा को स्थगन प्रस्ताव लाने की अनुमति नहीं है, और राष्ट्रपति के अभिभाषण पर धन्यवाद प्रस्ताव की हार का अर्थ है कि सरकार ने सदन का विश्वास खो दिया है। युग्म 2 गलत है: निंदा प्रस्ताव किसी एक मंत्री, मंत्रियों के समूह या पूरी मंत्रिपरिषद के विरुद्ध लाया जा सकता है। युग्म 3 दोनों प्रस्तावों को बदल देता है: निंदा प्रस्ताव में उसे स्वीकार करने के कारण बताना ज़रूरी है; अविश्वास प्रस्ताव में नहीं।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. स्थगन प्रस्ताव", "2. निंदा प्रस्ताव", "3. अविश्वास प्रस्ताव", "4. धन्यवाद प्रस्ताव"], "list_2_hi": ["केवल लोकसभा में लाया जा सकता है", "केवल पूरी मंत्रिपरिषद के विरुद्ध लाया जा सकता है", "इसमें इसे स्वीकार करने के कारण बताने होते हैं", "लोकसभा में इसकी हार सरकार की हार मानी जाती है"]}'::jsonb where id = '47c03918-efdb-4e27-8cf3-2ba08ddf8618' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'संविधान के अनुच्छेदों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'युग्म 1, 2 और 3 सही हैं: अनुच्छेद 105 संसदीय विशेषाधिकारों से संबंधित है, अनुच्छेद 110 धन विधेयक की परिभाषा देता है, और अनुच्छेद 112 वार्षिक वित्तीय विवरण (बजट) को संसद के समक्ष रखना अनिवार्य करता है। युग्म 4 गलत है: अनुच्छेद 123 राष्ट्रपति की अध्यादेश जारी करने की शक्ति है; राज्यपाल की ऐसी शक्ति अनुच्छेद 213 में है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. अनुच्छेद 105", "2. अनुच्छेद 110", "3. अनुच्छेद 112", "4. अनुच्छेद 123"], "list_2_hi": ["संसद के सदनों और उनके सदस्यों की शक्तियाँ और विशेषाधिकार", "धन विधेयक की परिभाषा", "वार्षिक वित्तीय विवरण", "राज्यपाल की अध्यादेश जारी करने की शक्ति"]}'::jsonb where id = '97bcd442-92e5-484a-a40c-b525873e22e4' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'किशोर न्याय (बालकों की देखरेख और संरक्षण) अधिनियम, 2015 के तहत, प्रारंभिक मूल्यांकन के बाद, 16 से 18 वर्ष आयु वर्ग के बालक पर किस श्रेणी के अपराधों के लिए वयस्क के रूप में मुकदमा चलाया जा सकता है?', explanation_hi = '2015 का अधिनियम 16 से 18 वर्ष के ऐसे बालक पर, जिस पर जघन्य अपराध (कम से कम सात वर्ष के कारावास से दंडनीय) का आरोप हो, किशोर न्याय बोर्ड द्वारा उसकी मानसिक और शारीरिक क्षमता के प्रारंभिक मूल्यांकन के बाद वयस्क के रूप में मुकदमा चलाने की अनुमति देता है। छोटे (petty) और गंभीर (serious) अपराध किशोर न्याय व्यवस्था के भीतर ही रहते हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "कोई भी अपराध", "b": "जघन्य अपराध", "c": "छोटे अपराध", "d": "गंभीर अपराध"}'::jsonb as hi) h) where id = '20b51c6e-9583-49ef-87de-7ff81ff80655' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। धारा 24 दूसरी अनुसूची के संगठनों को छूट देती है, जिसमें भ्रष्टाचार और मानवाधिकार वाला अपवाद है। धारा 22 अलग से RTI अधिनियम को शासकीय गुप्त बात अधिनियम और अन्य असंगत कानूनों पर अधिभावी प्रभाव (overriding effect) देती है। कथन-I की छूट धारा 24 के कारण है, अधिभावी खंड के कारण नहीं; बल्कि अधिभावी खंड तो उलटी दिशा में काम करता है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "सूचना का अधिकार अधिनियम, 2005 अपनी दूसरी अनुसूची में उल्लिखित आसूचना और सुरक्षा संगठनों पर लागू नहीं होता, सिवाय भ्रष्टाचार और मानवाधिकार उल्लंघन के आरोपों से संबंधित सूचना के।", "reason_hi": "सूचना का अधिकार अधिनियम, 2005 के प्रावधान शासकीय गुप्त बात अधिनियम, 1923 में किसी भी असंगत बात के होते हुए भी प्रभावी होते हैं।"}'::jsonb where id = '95c50024-5d33-4b11-b67f-c49ee84cd3d5' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'हाल के कानूनों और उनके द्वारा प्रतिस्थापित या निरस्त पुराने कानूनों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल युग्म 1 और 2 सही हैं। भारतीय वायुयान अधिनियम, 2024 (1 जनवरी 2025 से लागू) ने वायुयान अधिनियम, 1934 को निरस्त किया, और आप्रवास और विदेशियों विषयक अधिनियम, 2025 (1 सितंबर 2025 से लागू) ने विदेशियों विषयक अधिनियम, 1946 को तीन अन्य कानूनों के साथ निरस्त किया। युग्म 3 गलत है: भारतीय साक्ष्य अधिनियम ने भारतीय साक्ष्य अधिनियम, 1872 (Indian Evidence Act) की जगह ली। युग्म 4 गलत है: दूरसंचार अधिनियम ने भारतीय तार अधिनियम, 1885 और भारतीय बेतार तारयांत्रिकी अधिनियम, 1933 की जगह ली; केबल टेलीविज़न अपने 1995 के अधिनियम के तहत ही है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. भारतीय वायुयान अधिनियम, 2024", "2. आप्रवास और विदेशियों विषयक अधिनियम, 2025", "3. भारतीय साक्ष्य अधिनियम, 2023", "4. दूरसंचार अधिनियम, 2023"], "list_2_hi": ["वायुयान अधिनियम, 1934", "विदेशियों विषयक अधिनियम, 1946", "दंड प्रक्रिया संहिता, 1973", "केबल टेलीविज़न नेटवर्क (विनियमन) अधिनियम, 1995"]}'::jsonb where id = '9d649705-9f12-44ac-9fc2-91a99ae348c8' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'भारतीय न्याय संहिता (BNS) और भारतीय नागरिक सुरक्षा संहिता (BNSS), 2023 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1, 3 और 4 सही हैं: BNS में छोटे अपराधों के लिए सामुदायिक सेवा एक नया दंड है; BNSS की धारा 176(3) सात वर्ष या अधिक से दंडनीय अपराधों में घटनास्थल पर फ़ॉरेंसिक जाँच अनिवार्य करती है; और BNSS की धारा 356 मुकदमे से बचने के लिए फ़रार घोषित अपराधियों पर उनकी अनुपस्थिति में मुकदमा चलाने की अनुमति देती है। कथन 2 गलत है: BNS में ''राजद्रोह'' नाम का अपराध हटा दिया गया है; इसके बजाय धारा 152 अलग शब्दों में भारत की संप्रभुता, एकता और अखंडता को खतरे में डालने वाले कृत्यों को दंडित करती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["BNS कुछ छोटे अपराधों के लिए दंड के रूप में सामुदायिक सेवा शुरू करती है।", "BNS राजद्रोह के अपराध को उसी नाम से और भारतीय दंड संहिता की धारा 124क के समान शब्दों में बनाए रखती है।", "BNSS के तहत सात वर्ष या उससे अधिक के कारावास से दंडनीय अपराधों में फ़ॉरेंसिक विशेषज्ञ का घटनास्थल पर जाना अनिवार्य है।", "BNSS कुछ परिस्थितियों में घोषित अपराधियों पर उनकी अनुपस्थिति में मुकदमा चलाने का प्रावधान करती है।"]}'::jsonb where id = 'aa437b06-6dcd-43a2-a69d-c5afe7e2e098' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'दूरसंचार अधिनियम, 2023 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: अधिनियम ने औपनिवेशिक काल के तार और बेतार कानूनों की जगह ली, और यद्यपि स्पेक्ट्रम सामान्यतः नीलामी से दिया जाता है, धारा 4 और पहली अनुसूची सैटेलाइट-आधारित सेवाओं जैसे सूचीबद्ध उपयोगों के लिए प्रशासनिक आवंटन की अनुमति देती हैं। कथन 3 गलत है: TRAI, TRAI अधिनियम, 1997 के तहत बना हुआ है; दूरसंचार अधिनियम ने केवल उस अधिनियम के कुछ प्रावधानों में संशोधन किया।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने भारतीय तार अधिनियम, 1885 और भारतीय बेतार तारयांत्रिकी अधिनियम, 1933 को निरस्त कर दिया।", "यह अपनी पहली अनुसूची में सूचीबद्ध सेवाओं के लिए, जिनमें कुछ सैटेलाइट-आधारित सेवाएँ भी हैं, स्पेक्ट्रम नीलामी के बजाय प्रशासनिक प्रक्रिया से आवंटित करने की अनुमति देता है।", "इसने भारतीय दूरसंचार विनियामक प्राधिकरण (TRAI) को भंग कर दिया और उसके कार्य दूरसंचार विभाग को सौंप दिए।"]}'::jsonb where id = '0704edf2-0f35-4f58-bdf0-838e41d994f1' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = '2023 में पारित अधिनियमों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'युग्म 1, 2 और 4 सही हैं: मध्यस्थता अधिनियम ने मध्यस्थता के लिए एक सांविधिक ढाँचा बनाया (भारतीय मध्यस्थता परिषद और ऑनलाइन मध्यस्थता के प्रावधान के साथ), जन विश्वास अधिनियम ने व्यापार सुगमता के लिए 42 केंद्रीय अधिनियमों में छोटे अपराधों को अपराध की श्रेणी से बाहर किया, और डाकघर अधिनियम ने 1898 के कानून की जगह ली। युग्म 3 गलत है: प्रेस और पत्रिका पंजीकरण अधिनियम ने प्रेस और पुस्तक पंजीकरण अधिनियम, 1867 की जगह ली और यह प्रेस रजिस्ट्रार जनरल के माध्यम से पत्रिकाओं के पंजीकरण से संबंधित है; यह OTT मंचों का विनियमन नहीं करता।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. मध्यस्थता अधिनियम, 2023", "2. जन विश्वास (प्रावधानों का संशोधन) अधिनियम, 2023", "3. प्रेस और पत्रिका पंजीकरण अधिनियम, 2023", "4. डाकघर अधिनियम, 2023"], "list_2_hi": ["ऑनलाइन मध्यस्थता सहित मध्यस्थता का एक संस्थागत ढाँचा", "अनेक केंद्रीय कानूनों में छोटे अपराधों को अपराध की श्रेणी से बाहर करना", "OTT स्ट्रीमिंग मंचों का विनियमन", "भारतीय डाकघर अधिनियम, 1898 की जगह लेना"]}'::jsonb where id = 'fae84633-a5c3-4508-ba2a-717df0e2630c' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 के तहत व्यक्तिगत डेटा के उल्लंघन को रोकने के लिए उचित सुरक्षा उपाय न करने पर अधिकतम कितना जुर्माना लगाया जा सकता है?', explanation_hi = 'अधिनियम की अनुसूची उच्चतम जुर्माना, 250 करोड़ रुपये तक, व्यक्तिगत डेटा उल्लंघन को रोकने के लिए उचित सुरक्षा उपाय न करने पर तय करती है। उल्लंघन की सूचना न देने और बच्चों के डेटा संबंधी दायित्वों का उल्लंघन करने पर 200 करोड़ रुपये तक, महत्त्वपूर्ण डेटा न्यासियों (Significant Data Fiduciaries) के अतिरिक्त दायित्वों के उल्लंघन पर 150 करोड़ रुपये तक, और बाकी मामलों में 50 करोड़ रुपये तक का जुर्माना है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "250 करोड़ रुपये", "b": "200 करोड़ रुपये", "c": "150 करोड़ रुपये", "d": "50 करोड़ रुपये"}'::jsonb as hi) h) where id = '8243e111-e7e5-47f7-bba1-1ce5816c1e98' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: अधिनियम उल्लंघनों पर निर्णय के लिए भारतीय डेटा संरक्षण बोर्ड स्थापित करता है, और धारा 3 के तहत यह डिजिटल व्यक्तिगत डेटा पर लागू है, जिसमें ऑफ़लाइन एकत्र करके बाद में डिजिटल किया गया डेटा भी शामिल है। कथन 3 गलत है: भारत के बाहर का प्रसंस्करण तभी शामिल है जब वह भारत के भीतर डेटा प्रधानों (Data Principals) को वस्तुएँ या सेवाएँ देने से जुड़ा हो। नवंबर 2025 में अधिसूचित DPDP नियम अधिकांश दायित्वों को 18 महीनों में चरणबद्ध रूप से लागू करते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह भारतीय डेटा संरक्षण बोर्ड की स्थापना का प्रावधान करता है।", "यह डिजिटल रूप में एकत्र व्यक्तिगत डेटा पर, और गैर-डिजिटल रूप में एकत्र करके बाद में डिजिटल किए गए व्यक्तिगत डेटा पर लागू होता है।", "यह भारत के बाहर व्यक्तिगत डेटा के प्रसंस्करण पर तब भी लागू होता है जब वह प्रसंस्करण भारत में डेटा प्रधानों को वस्तुएँ या सेवाएँ देने से जुड़ा न हो।"]}'::jsonb where id = 'dc1df065-8dcc-4400-aecf-78b12b2e3984' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सूचना का अधिकार अधिनियम, 2005 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं। धारा 7(1) का परंतुक किसी व्यक्ति के जीवन या स्वतंत्रता से संबंधित सूचना 48 घंटे में देना अनिवार्य करता है (सामान्य सीमा 30 दिन है)। 2019 के संशोधन ने पाँच वर्ष का निश्चित कार्यकाल और निर्वाचन आयोग के समान वेतन की व्यवस्था हटा दी, और दोनों बातें केंद्र सरकार के नियमों से तय होने के लिए छोड़ दीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["किसी व्यक्ति के जीवन या स्वतंत्रता से संबंधित सूचना अनुरोध प्राप्त होने के 48 घंटे के भीतर देनी होती है।", "सूचना का अधिकार (संशोधन) अधिनियम, 2019 ने केंद्र सरकार को मुख्य सूचना आयुक्त और सूचना आयुक्तों का कार्यकाल और वेतन निर्धारित करने का अधिकार दिया।"]}'::jsonb where id = 'ace4188a-cb92-44a0-a265-e959e4c4fd64' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'भारत के नए आपराधिक कानूनों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। कथन 2 कानूनों को आपस में बदल देता है: भारतीय साक्ष्य अधिनियम ने भारतीय साक्ष्य अधिनियम, 1872 (Indian Evidence Act) की जगह ली, जबकि दंड प्रक्रिया संहिता की जगह भारतीय नागरिक सुरक्षा संहिता, 2023 ने ली। कथन 3 गलत है: तीनों कानून दिसंबर 2023 में बने, पर 1 जुलाई 2024 से लागू हुए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भारतीय न्याय संहिता, 2023 ने भारतीय दंड संहिता, 1860 की जगह ली।", "भारतीय साक्ष्य अधिनियम, 2023 ने दंड प्रक्रिया संहिता, 1973 की जगह ली।", "तीनों नए आपराधिक कानून 1 जनवरी 2024 से लागू हुए।"]}'::jsonb where id = 'c5838d54-fda9-4caf-a642-fbad7818e870' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सार्वजनिक परीक्षा (अनुचित साधनों की रोकथाम) अधिनियम, 2024 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: अधिनियम अपनी अनुसूची में सूचीबद्ध सार्वजनिक परीक्षा प्राधिकरणों पर लागू है, जिनमें UPSC, SSC, रेलवे भर्ती बोर्ड, IBPS और NTA के साथ केंद्रीय मंत्रालय और विभाग भी हैं। कथन 1 गलत है: अधिनियम के तहत हर अपराध संज्ञेय, अजमानतीय और अशमनीय (non-compoundable) है। कथन 3 गलत है: अधिनियम केंद्रीय परीक्षाओं पर लागू है; राज्य की परीक्षाएँ इसके बाहर हैं, जब तक कोई राज्य इसे अपना न ले या अपना कानून न बनाए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इस अधिनियम के तहत अपराध जमानतीय हैं और परीक्षा प्राधिकरण की सहमति से उनका शमन (compounding) हो सकता है।", "यह संघ लोक सेवा आयोग, कर्मचारी चयन आयोग और राष्ट्रीय परीक्षा एजेंसी जैसे निकायों द्वारा आयोजित सार्वजनिक परीक्षाओं पर लागू होता है।", "यह राज्य लोक सेवा आयोगों द्वारा आयोजित भर्ती परीक्षाओं पर सीधे लागू होता है।"]}'::jsonb where id = '5e604ede-cda2-48e3-8cfc-f02c9cc8450a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I सही है: POCSO अधिनियम लिंग की परवाह किए बिना सभी बच्चों को यौन अपराधों से संरक्षण देता है। कथन-II गलत है: धारा 2(1)(घ) बालक को अठारह वर्ष से कम आयु के किसी भी व्यक्ति के रूप में परिभाषित करती है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "लैंगिक अपराधों से बालकों का संरक्षण (POCSO) अधिनियम, 2012 एक लिंग-तटस्थ (gender-neutral) कानून है।", "reason_hi": "POCSO अधिनियम के तहत ''बालक'' का अर्थ सोलह वर्ष से कम आयु का कोई भी व्यक्ति है।"}'::jsonb where id = '37d8474c-9028-42d3-97f3-72ea734094e2' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'जब राष्ट्रपति और उपराष्ट्रपति, दोनों के पद रिक्त हों, तब भारत के राष्ट्रपति के कार्यों का निर्वहन कौन करता है?', explanation_hi = 'राष्ट्रपति (कृत्यों का निर्वहन) अधिनियम, 1969 के तहत दोनों पद रिक्त होने पर भारत के मुख्य न्यायाधीश, या वह पद भी रिक्त हो तो उच्चतम न्यायालय के सबसे वरिष्ठ उपलब्ध न्यायाधीश, नए राष्ट्रपति के निर्वाचन तक राष्ट्रपति के कार्यों का निर्वहन करते हैं। 1969 में ऐसा हुआ था, जब मुख्य न्यायाधीश एम. हिदायतुल्लाह ने कार्यवाहक राष्ट्रपति के रूप में काम किया।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "प्रधानमंत्री", "b": "भारत के मुख्य न्यायाधीश", "c": "लोकसभा अध्यक्ष", "d": "राज्यसभा के उपसभापति"}'::jsonb as hi) h) where id = 'db5f6694-968a-43c0-b873-52f074c42887' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत के प्रधानमंत्री के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 गलत है: अनुच्छेद 75 केवल इतना कहता है कि प्रधानमंत्री की नियुक्ति राष्ट्रपति करेंगे, चयन की कोई प्रक्रिया नहीं बताता; परंपरा के अनुसार राष्ट्रपति लोकसभा में बहुमत दल या गठबंधन के नेता को नियुक्त करते हैं। कथन 2 गलत है: किसी भी सदन के सदस्य को, या किसी गैर-सदस्य को भी, नियुक्त किया जा सकता है, जिसे छह महीने में किसी सदन का सदस्य बनना होता है; कई प्रधानमंत्री राज्यसभा के सदस्य रहे हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संविधान प्रधानमंत्री के चयन और नियुक्ति की एक विशिष्ट प्रक्रिया निर्धारित करता है।", "प्रधानमंत्री के रूप में नियुक्ति के समय व्यक्ति का लोकसभा का सदस्य होना आवश्यक है।"]}'::jsonb where id = '9865bafc-ecc8-410d-b4d0-ba63973100a0' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'मुख्यमंत्री और राज्य मंत्रिपरिषद के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। मुख्यमंत्री की नियुक्ति राष्ट्रपति नहीं, राज्यपाल करते हैं (अनुच्छेद 164(1))। कोई गैर-सदस्य नियुक्त हो सकता है, पर उसे तीन नहीं, छह महीने में राज्य विधानमंडल का सदस्य बनना होता है (अनुच्छेद 164(4))। 91वें संशोधन द्वारा जोड़े गए अनुच्छेद 164(1क) के तहत मुख्यमंत्री सहित मंत्रियों की कुल संख्या विधानसभा की सदस्य संख्या के 15 प्रतिशत से अधिक नहीं हो सकती, पर बारह से कम भी नहीं हो सकती।', updated_at = now(), question_data = question_data || '{"statements_hi": ["मुख्यमंत्री की नियुक्ति राष्ट्रपति राज्यपाल की सिफ़ारिश पर करते हैं।", "राज्य विधानमंडल का सदस्य न होने वाला व्यक्ति मुख्यमंत्री नियुक्त हो सकता है, पर उसे तीन महीने के भीतर विधानमंडल के लिए निर्वाचित होना होगा।", "किसी राज्य में मुख्यमंत्री सहित मंत्रियों की कुल संख्या पंद्रह से कम नहीं हो सकती।"]}'::jsonb where id = '20f02c32-ad3f-4e44-8433-b5fedd5bd227' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राज्य विधेयकों पर स्वीकृति से संबंधित राष्ट्रपतीय संदर्भ पर उच्चतम न्यायालय की नवंबर 2025 की राय के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। तमिलनाडु राज्य बनाम तमिलनाडु के राज्यपाल (अप्रैल 2025) में दो न्यायाधीशों की पीठ ने समय-सीमाएँ तय की थीं और दस विधेयकों को ''मानी गई'' स्वीकृति वाला घोषित किया था; इसके बाद राष्ट्रपति ने अनुच्छेद 143 के तहत न्यायालय की राय माँगी। 20 नवंबर 2025 को संविधान पीठ ने राय दी कि न्यायालय राज्यपाल या राष्ट्रपति पर समय-सीमाएँ नहीं थोप सकते। कथन 3 गलत है: न्यायालय ने ''मानी गई स्वीकृति'' (deemed assent) की अवधारणा को अस्वीकार किया। कथन 4 गलत है: न्यायालय ने यह भी कहा कि राज्यपाल विधेयकों को अनिश्चित काल तक रोककर नहीं बैठ सकते; लंबी, बिना कारण की निष्क्रियता पर सीमित न्यायिक समीक्षा हो सकती है, जिसमें न्यायालय गुण-दोष में गए बिना निर्णय लेने का निर्देश दे सकता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह संदर्भ राष्ट्रपति ने संविधान के अनुच्छेद 143 के तहत भेजा था।", "न्यायालय ने राय दी कि संवैधानिक न्यायालय अनुच्छेद 200 के तहत प्रस्तुत विधेयकों पर राज्यपाल के निर्णय के लिए समय-सीमाएँ निर्धारित नहीं कर सकते।", "न्यायालय ने कहा कि यदि राज्यपाल उचित समय में किसी विधेयक पर निर्णय न लें, तो उसे स्वीकृति प्राप्त माना जा सकता है।", "न्यायालय ने कहा कि राज्यपाल बिना कोई निर्णय बताए किसी विधेयक को अनिश्चित काल तक लंबित रख सकते हैं।"]}'::jsonb where id = 'a9857250-83ab-4dbb-823f-bf1a709e7187' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'भारत के उपराष्ट्रपति के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं: अनुच्छेद 66 के तहत निर्वाचक मंडल में संसद के दोनों सदनों के सभी सदस्य, निर्वाचित और मनोनीत, होते हैं; और अनुच्छेद 67(ख) के तहत उपराष्ट्रपति को राज्यसभा के तत्कालीन सभी सदस्यों के बहुमत से पारित और लोकसभा द्वारा सहमत प्रस्ताव से हटाया जाता है, महाभियोग की आवश्यकता नहीं है। कथन 2 गलत है: राष्ट्रपति के निर्वाचक मंडल के विपरीत, उपराष्ट्रपति के निर्वाचक मंडल में राज्य विधानसभाओं के सदस्य नहीं होते। कथन 4 गलत है: अनुच्छेद 68(2) के तहत त्यागपत्र से हुई रिक्ति को भरने के लिए चुना गया व्यक्ति पद ग्रहण करने की तिथि से पूरे पाँच वर्ष का कार्यकाल पाता है; इसलिए 9 सितंबर 2025 को चुने गए सी.पी. राधाकृष्णन का कार्यकाल पूरे पाँच वर्ष का है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["उपराष्ट्रपति का निर्वाचन संसद के दोनों सदनों के सदस्यों से बने निर्वाचक मंडल द्वारा होता है।", "राष्ट्रपति के निर्वाचन की तरह, उपराष्ट्रपति के निर्वाचन में भी राज्य विधानसभाओं के निर्वाचित सदस्य मत देते हैं।", "उपराष्ट्रपति को हटाने के लिए औपचारिक महाभियोग की आवश्यकता नहीं है।", "मध्यावधि रिक्ति के बाद सितंबर 2025 में निर्वाचित उपराष्ट्रपति केवल अपने पूर्ववर्ती के शेष कार्यकाल तक पद पर रहेंगे।"]}'::jsonb where id = '9a9120ab-9d52-4326-a524-8fa0e1c0cb45' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'किसी राज्य के राज्यपाल के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: अनुच्छेद 155 राष्ट्रपति द्वारा अपने हस्ताक्षर और मुद्रा सहित अधिपत्र से नियुक्ति का प्रावधान करता है, और 7वें संशोधन (1956) ने एक ही व्यक्ति को दो या अधिक राज्यों का राज्यपाल बनने की अनुमति दी। कथन 3 गलत है: राज्यपाल राष्ट्रपति के प्रसादपर्यंत पद धारण करते हैं (अनुच्छेद 156) और संविधान हटाने के कोई आधार नहीं बताता; यद्यपि बी.पी. सिंघल (2010) में उच्चतम न्यायालय ने कहा कि इस प्रसाद का प्रयोग मनमाने ढंग से नहीं हो सकता।', updated_at = now(), question_data = question_data || '{"statements_hi": ["राज्यपाल की नियुक्ति राष्ट्रपति अपने हस्ताक्षर और मुद्रा सहित अधिपत्र द्वारा करते हैं।", "एक ही व्यक्ति को दो या अधिक राज्यों का राज्यपाल नियुक्त किया जा सकता है।", "संविधान उन आधारों को निर्धारित करता है जिन पर राज्यपाल को पद से हटाया जा सकता है।"]}'::jsonb where id = '956683d1-3b64-4493-9c7b-d93fd821cc95' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संविधान के अनुच्छेदों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल युग्म 1 सही है: अनुच्छेद 74 राष्ट्रपति को सहायता और सलाह देने के लिए मंत्रिपरिषद का प्रावधान करता है। युग्म 2 गलत है: प्रधानमंत्री का सूचना देने का कर्तव्य अनुच्छेद 78 में है (अनुच्छेद 75 मंत्रियों की नियुक्ति और उनसे संबंधित अन्य प्रावधानों से जुड़ा है)। युग्म 3 गलत है: अनुच्छेद 164 राज्यपाल द्वारा मुख्यमंत्री की नियुक्ति का प्रावधान करता है। युग्म 4 गलत है: मुख्यमंत्री का सूचना देने का कर्तव्य अनुच्छेद 167 में है; अनुच्छेद 166 राज्य सरकार के कार्य-संचालन से संबंधित है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. अनुच्छेद 74", "2. अनुच्छेद 75", "3. अनुच्छेद 164", "4. अनुच्छेद 166"], "list_2_hi": ["राष्ट्रपति को सहायता और सलाह देने के लिए मंत्रिपरिषद", "राष्ट्रपति को सूचना देने के संबंध में प्रधानमंत्री के कर्तव्य", "राष्ट्रपति द्वारा मुख्यमंत्री की नियुक्ति", "राज्यपाल को सूचना देने के संबंध में मुख्यमंत्री के कर्तव्य"]}'::jsonb where id = '128392b2-fa60-4c73-9218-66468bd7c808' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I सही है: अनुच्छेद 75(2) के तहत प्रधानमंत्री सहित मंत्री राष्ट्रपति के प्रसादपर्यंत पद धारण करते हैं। कथन-II गलत है: चूँकि मंत्रिपरिषद सामूहिक रूप से लोकसभा के प्रति उत्तरदायी है (अनुच्छेद 75(3)), इसलिए व्यवहार में राष्ट्रपति के प्रसाद का अर्थ है कि जब तक प्रधानमंत्री को लोकसभा का विश्वास प्राप्त है, उन्हें बर्खास्त नहीं किया जा सकता।', updated_at = now(), question_data = question_data || '{"assertion_hi": "प्रधानमंत्री राष्ट्रपति के प्रसादपर्यंत पद धारण करते हैं।", "reason_hi": "राष्ट्रपति अपने विवेक से प्रधानमंत्री को किसी भी समय बर्खास्त कर सकते हैं, तब भी जब प्रधानमंत्री को लोकसभा का विश्वास प्राप्त हो।"}'::jsonb where id = '380e0ce1-04ee-4be6-ac9e-b53aeae767ce' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित में से कौन-सी किसी राज्य के राज्यपाल की शक्ति नहीं है?', explanation_hi = 'उच्च न्यायालय के न्यायाधीशों की नियुक्ति राष्ट्रपति करते हैं (अनुच्छेद 217); राज्यपाल से केवल परामर्श किया जाता है। राज्यपाल महाधिवक्ता की नियुक्ति करते हैं (अनुच्छेद 165), विधान परिषद के छठे भाग सदस्यों को मनोनीत करते हैं (अनुच्छेद 171), और राज्य विधानमंडल का सत्र बुलाते तथा सत्रावसान करते हैं (अनुच्छेद 174)।', updated_at = now() where id = 'ec96412e-d646-4c45-810b-8ade62d1f0e6' and exam_category = 'upsc' returning id;
